// Turns the store API's answer into short facts for the assistant. A 404 never says whether the order exists.
const res = $input.first().json;
const order = res.body ?? {};
if (res.statusCode !== 200) {
  return [{ json: { found: false, message: 'No order matches that order number and email. Ask the customer to check both (the email must be the one used at checkout).' } }];
}
const date = (iso) => iso ? new Date(iso + 'T12:00:00Z').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' }) : null;
const items = (order.items ?? []).map((i) => (i.qty > 1 ? i.qty + ' x ' : '') + i.name).join(', ');
const STATUS = {
  processing: 'Being packed at the warehouse. Estimated delivery ' + date(order.estimated_delivery) + '.',
  shipped: 'Shipped with ' + order.carrier + ', tracking number ' + order.tracking_number + '. Estimated delivery ' + date(order.estimated_delivery) + '.',
  delivered: 'Delivered on ' + date(order.delivered_at) + ' by ' + order.carrier + ' (tracking ' + order.tracking_number + ').',
  backordered: 'Waiting on a backordered item. Estimated delivery ' + date(order.estimated_delivery) + '.',
  return_in_progress: 'Return received on ' + date(order.return?.received_at) + '. Refund ' + (order.return?.refund_status ?? 'processing')
    + ', expected by ' + date(order.return?.refund_expected_by) + '.',
};
return [{ json: {
  found: true,
  order_number: order.number,
  placed: date(order.placed_at),
  items,
  status: order.status,
  summary: STATUS[order.status] ?? 'Status: ' + order.status + '.',
  note: order.note ?? null,
} }];
